import perceivo


def _evaluate(actual, operator, expected):
    """Evaluate a single condition."""
    if actual is None:
        return False

    actual_str = str(actual)
    expected_str = str(expected)

    if operator == "equals":
        return actual_str.lower() == expected_str.lower()
    elif operator == "not_equals":
        return actual_str.lower() != expected_str.lower()
    elif operator == "contains":
        return expected_str.lower() in actual_str.lower()
    elif operator == "starts_with":
        return actual_str.lower().startswith(expected_str.lower())
    elif operator == "greater_than":
        try:
            return float(actual) > float(expected)
        except (ValueError, TypeError):
            return False
    elif operator == "greater_than_or_equal":
        try:
            return float(actual) >= float(expected)
        except (ValueError, TypeError):
            return False
    elif operator == "less_than":
        try:
            return float(actual) < float(expected)
        except (ValueError, TypeError):
            return False
    elif operator == "less_than_or_equal":
        try:
            return float(actual) <= float(expected)
        except (ValueError, TypeError):
            return False
    else:
        perceivo.log.warning(f"Unknown operator: {operator}, treating as no match")
        return False



@perceivo.policy
async def conditional_router_policy_internal(input: perceivo.primitives.PolicyInput) -> perceivo.primitives.PolicyOutput:
    request_data = input.request_data or {}

    # Branch config is passed from the Layer in request_data
    branches = request_data.get("branches", [])
    default_branch = request_data.get("default_branch", "")
    data = request_data.get("data", {})

    perceivo.log.info(
        f"Evaluating {len(branches)} conditions",
        default_branch=default_branch,
        data_keys=list(data.keys()) if isinstance(data, dict) else [],
    )

    # Evaluate conditions in order -- first match wins
    target = default_branch
    match_reason = "default (no conditions matched)"
    matched = False

    for branch in branches:
        port_name = branch.get("port_name", "")
        field = branch.get("field", "")
        operator = branch.get("operator", "equals")
        expected = branch.get("value", "")

        actual = data.get(field) if isinstance(data, dict) else None

        if _evaluate(actual, operator, expected):
            target = port_name
            match_reason = f"{field} {operator} {expected}"
            matched = True
            perceivo.log.info(f"Condition matched: {match_reason} -> {target}")
            break

    # Fail-closed: if nothing matched and no explicit default_branch
    # was configured, refuse to route rather than silently falling through to
    # branch_1. A user can still set default_branch to opt into a fallback.
    if not matched and not default_branch:
        raise ValueError(
            "Conditional Router: no branch condition matched and no "
            "default_branch is configured; failing closed. Set an explicit "
            "default_branch to enable a fallback route."
        )

    perceivo.log.info(f"Decision: route to {target} ({match_reason})")

    return perceivo.primitives.PolicyOutput(
        next_state=target,
        response_data={
            "next_state": target,
            "match_reason": match_reason,
        }
    )

